import { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "../css/login.css";

function Login() {
  const navigate = useNavigate();
  const [studentId, setStudentId] = useState("");
  const [password, setPassword] = useState("");

  const login = async () => {
    if (!studentId.trim() || !password) {
      alert("กรุณากรอกข้อมูล");
      return;
    }

    try {
      const response = await axios.post(
        "http://localhost:5001/login",
        {
          username: studentId.trim(),
          password: password
        }
      );

      const data = response.data;

      if (data.success) {
        const faculty = (
          data.user?.faculty ||
          data.user?.faculty_name_th ||
          data.user?.faculty_name_en ||
          ""
        ).trim().toLowerCase();

        const allowedFaculties = [
          "คณะวิทยาศาสตร์และเทคโนโลยี",
          "วิทยาศาสตร์และเทคโนโลยี",
          "faculty of science and technology",
          "science and technology",
          "faculty of science & technology"
        ];

        if (!allowedFaculties.includes(faculty)) {
          alert(
            "ขออภัย ระบบเปิดให้บริการเฉพาะบุคลากรคณะวิทยาศาสตร์"
          );
          return;
        }

        localStorage.setItem("token", data.token);
        localStorage.setItem("user", JSON.stringify(data.user));

        navigate("/homepage");
      }
    } catch (error) {
      console.log("Login error:", error);

      if (error.response?.status === 403) {
        alert(
          error.response.data?.message ||
          "ขออภัย ระบบเปิดให้บริการเฉพาะบุคลากรคณะวิทยาศาสตร์"
        );
      } else {
        alert(
          error.response?.data?.message ||
          "เข้าสู่ระบบไม่สำเร็จ กรุณาตรวจสอบ Username และ Password"
        );
      }
    }
  };

  return (
    <div className="login-page">
      <div className="left-section">
        <div className="logo-wrapper">
          <img
            src={`${process.env.PUBLIC_URL}/logo.png`}
            alt="logo"
            className="logo"
          />
        </div>

        <div className="booking-wrapper">
          <h1>BOOKING ROOM</h1>
          <div className="booking-line"></div>
          <p>
            Learning Center 2
            <br />
            Thammasat University (Rangsit Campus)
          </p>
        </div>
      </div>

      <div className="right-section">
        <div className="login-box">
          <div className="login-title">LOGIN</div>

          <div className="form-wrapper">
            <label>USERNAME</label>
            <input
              type="text"
              placeholder="enter your username"
              value={studentId}
              onChange={(e) => setStudentId(e.target.value)}
            />

            <label>PASSWORD</label>
            <input
              type="password"
              placeholder="enter your password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />

            <div className="button-wrapper">
              <button onClick={login}>ENTER</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Login;
